#nullable enable // autogenerated

using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using Tools;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.lightningOrbEnergyShieldBreak)]
    public class LightningOrbEnergyShieldBreakBuff : BuffDefinition
    {
        public LightningOrbEnergyShieldBreakBuff(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.PRE_ENTITY_TAKE_DAMAGE, PreEntityTakeDamageCallback);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var evoked = buff.GetProperty<bool>(PROP_EVOKED);
            var entity = buff.GetEntity();
            buff.Remove();
            if (evoked && entity.ExistsAndAlive())
            {
                entity.AddBuff<LightningOrbEvokedBuff>();
            }
        }
        private void PreEntityTakeDamageCallback(VanillaLevelCallbacks.PreTakeDamageParams param, CallbackResult result)
        {
            var damage = param.input;
            var entity = damage.Entity;
            foreach (var buff in entity.GetBuffs<LightningOrbEnergyShieldBreakBuff>())
            {
                result.SetFinalValue(false);
            }
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
        public static readonly VanillaBuffPropertyMeta<bool> PROP_EVOKED = new VanillaBuffPropertyMeta<bool>("evoked");
    }
}
